    worstF:[['Low Beta','Avoid'],['Dividend Yield','Avoid'],['Value','Avoid'],['Defensives','Avoid'],['Size','Avoid']],
    bestFI:[['Convertibles','Long'],['BDCs','Long'],['Preferreds','Long'],['Leveraged Loans','Long'],['HY Credit','Long']],
